#include <iostream>
struct Engine{ bool running=false; void start(){running=true;} };
struct Dashboard{ void show(bool running) const{std::cout<<(running?"running":"stopped")<<'\n';} };
struct Car{ Engine engine; Dashboard dash; void start(){engine.start();dash.show(engine.running);} };
int main(){ Car c; c.start(); }

#include <iostream>
#include <string_view>
struct Logger{ virtual ~Logger()=default; virtual void write(std::string_view)=0; };
struct ConsoleLogger:Logger{ void write(std::string_view s) override{std::cout<<s<<'\n';} };
struct Service{ Logger& log; void run(){log.write("service running");} };
int main(){ ConsoleLogger l; Service s{l}; s.run(); }
